import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, convert, formatMoney, RATES } from '../src/money.js';

test('roundCents rounds half to even', () => {
  assert.equal(roundCents(124.5), 124);
  assert.equal(roundCents(125.5), 126);
  assert.equal(roundCents(2.4), 2);
  assert.equal(roundCents(2.6), 3);
  assert.equal(roundCents(-0.5), 0);
});

test('roundCents ignores binary noise', () => {
  assert.equal(roundCents(0.1 * 3 * 100), 30);
  assert.equal(roundCents(1.005 * 100), 100);
});

test('formatEuros adds the sign, thousands separators and two decimals', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
  assert.equal(formatEuros(5), '€0.05');
  assert.equal(formatEuros(-250), '-€2.50');
  assert.equal(formatEuros(100000000), '€1,000,000.00');
});

test('parseEuros reads what people type', () => {
  assert.deepEqual(parseEuros('12'), { ok: true, value: 1200 });
  assert.deepEqual(parseEuros('12.5'), { ok: true, value: 1250 });
  assert.deepEqual(parseEuros('1,234.56'), { ok: true, value: 123456 });
  assert.deepEqual(parseEuros('12.345'), { ok: false, error: 'AMOUNT_INVALID' });
  assert.deepEqual(parseEuros('abc'), { ok: false, error: 'AMOUNT_INVALID' });
});

test('RATES has correct conversion rates', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert returns ok for valid EUR conversion', () => {
  const result = convert(10000, 'EUR');

  assert.equal(result.ok, true);
  assert.equal(result.value, 10000);
});

test('convert converts EUR to USD', () => {
  const result = convert(10000, 'USD');

  assert.equal(result.ok, true);
  // 10000 cents * 1.085 = 10850 cents
  assert.equal(result.value, 10850);
});

test('convert converts EUR to GBP', () => {
  const result = convert(10000, 'GBP');

  assert.equal(result.ok, true);
  // 10000 cents * 0.8425 = 8425 cents
  assert.equal(result.value, 8425);
});

test('convert with large amount', () => {
  const result = convert(1000000, 'USD');

  assert.equal(result.ok, true);
  // 1000000 * 1.085 = 1085000
  assert.equal(result.value, 1085000);
});

test('convert with small amount', () => {
  const result = convert(5, 'USD');

  assert.equal(result.ok, true);
  // 5 * 1.085 = 5.425 → 5 (rounds half to even)
  assert.equal(result.value, 5);
});

test('convert rejects unknown currency', () => {
  const result = convert(10000, 'JPY');

  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_CURRENCY' });
});

test('convert rejects negative amount', () => {
  const result = convert(-1000, 'USD');

  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('convert rejects non-integer amount', () => {
  const result = convert(1000.5, 'USD');

  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('convert handles zero amount', () => {
  const result = convert(0, 'USD');

  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('formatMoney formats EUR', () => {
  const result = formatMoney(123456, 'EUR');

  assert.equal(result.ok, true);
  assert.equal(result.value, '€1,234.56');
});

test('formatMoney formats USD', () => {
  const result = formatMoney(10000, 'USD');

  assert.equal(result.ok, true);
  // 10000 * 1.085 = 10850 cents = $108.50
  assert.equal(result.value, '$108.50');
});

test('formatMoney formats GBP', () => {
  const result = formatMoney(10000, 'GBP');

  assert.equal(result.ok, true);
  // 10000 * 0.8425 = 8425 cents = £84.25
  assert.equal(result.value, '£84.25');
});

test('formatMoney with thousands separators USD', () => {
  const result = formatMoney(1234567, 'USD');

  assert.equal(result.ok, true);
  // 1234567 * 1.085 = 1338645.095 → 1338645 cents = $13,386.45
  assert.equal(result.value, '$13,386.45');
});

test('formatMoney with small amount USD', () => {
  const result = formatMoney(5, 'USD');

  assert.equal(result.ok, true);
  // 5 * 1.085 = 5.425 → 5 cents = $0.05
  assert.equal(result.value, '$0.05');
});

test('formatMoney with zero amount', () => {
  const result = formatMoney(0, 'EUR');

  assert.equal(result.ok, true);
  assert.equal(result.value, '€0.00');
});

test('formatMoney rejects unknown currency', () => {
  const result = formatMoney(10000, 'CHF');

  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_CURRENCY' });
});

test('formatMoney with GBP large amount', () => {
  const result = formatMoney(100000000, 'GBP');

  assert.equal(result.ok, true);
  // 100000000 * 0.8425 = 84250000 cents = £842,500.00
  assert.equal(result.value, '£842,500.00');
});

test('convert handles rounding correctly', () => {
  // Test that fractional cents are rounded properly
  const result = convert(333, 'USD');

  assert.equal(result.ok, true);
  // 333 * 1.085 = 361.155 → 361 (banker's rounding)
  assert.equal(result.value, 361);
});

test('convert USD to all currencies consistent', () => {
  const eur = convert(100000, 'EUR');
  const usd = convert(100000, 'USD');
  const gbp = convert(100000, 'GBP');

  assert.equal(eur.ok, true);
  assert.equal(usd.ok, true);
  assert.equal(gbp.ok, true);

  // USD should be greater than EUR
  assert(usd.value > eur.value);
  // GBP should be less than EUR
  assert(gbp.value < eur.value);
});
